import React, { useEffect, useState } from "react";
import { useLocation } from "react-router-dom";
import SidebarMenu from "./SidebarMenu";

const Layout = ({ children }) => {
  const location = useLocation();
  const hideSidebar = location.pathname.startsWith("/auth/login") || location.pathname === "/";
  const [module, setModule] = useState("");

  useEffect(() => {
    // Determine current module based on URL
    const path = location.pathname.split("/")[1]; // e.g., 'journal'
    setModule(path);
  }, [location.pathname]);

  // Initialize AdminLTE treeview for sidebar
  useEffect(() => {
    if (window.$) {
      try {
        $(".nav-sidebar").treeview();
      } catch (error) {
        console.log("Treeview initialization error:", error);
      }
    }
  }, []);

  // Handle sidebar toggle manually
  const handleSidebarToggle = (e) => {
    e.preventDefault();
    const body = document.body;
    
    // Toggle the sidebar-collapse class
    if (body.classList.contains("sidebar-collapse")) {
      body.classList.remove("sidebar-collapse");
    } else {
      body.classList.add("sidebar-collapse");
    }
  };

  return (
    <div className="wrapper hold-transition sidebar-mini layout-fixed">
      
      {!hideSidebar && (
        <nav className="main-header navbar navbar-expand navbar-white navbar-light">
          <ul className="navbar-nav">
            <li className="nav-item">
              <a 
                className="nav-link" 
                data-widget="pushmenu" 
                href="#" 
                role="button"
                onClick={handleSidebarToggle}
              >
                <i className="fas fa-bars"></i>
              </a>
            </li>
          </ul>
        </nav>
      )}

      {!hideSidebar && <SidebarMenu module={module} />}

      <div className="content-wrapper p-3">
        <section className="content container-fluid">{children}</section>
      </div>
    </div>
  );
};

export default Layout;
